"""Repair local links in a Markdown knowledge base and generate its indexes."""

from __future__ import annotations

import argparse
import csv
import json
import posixpath
import re
import shutil
import stat
import sys
import unicodedata
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Iterable


HEADING_RE = re.compile(
    r"^ *(#{1,6})(?:[^\S\r\n]+(.*?))?(?:\r?\n)?$"
)
FENCE_RE = re.compile(r"^ *(`{3,}|~{3,})")
SCHEME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")


@dataclass(frozen=True)
class Heading:
    text: str
    anchor: str


@dataclass(frozen=True)
class DocumentInfo:
    title: str
    headings: tuple[Heading, ...]


@dataclass(frozen=True)
class LinkResult:
    replacement: str | None
    resolved_target: str
    status: str


def normalize_anchor(value: str) -> str:
    """Return the canonical base anchor described by the task."""
    value = unicodedata.normalize("NFKC", value).casefold()
    value = "".join(
        char
        for char in value
        if char == "-" or not unicodedata.category(char).startswith("P")
    )
    value = re.sub(r"\s+", "-", value)
    value = re.sub(r"-+", "-", value)
    return value.strip("-")


def fence_lines(lines: list[str]) -> list[bool]:
    """Mark opening, closing, and interior fenced-code lines."""
    result: list[bool] = []
    marker: str | None = None
    minimum = 0
    for line in lines:
        if marker is None:
            match = FENCE_RE.match(line)
            if match is None:
                result.append(False)
                continue
            run = match.group(1)
            marker = run[0]
            minimum = len(run)
            result.append(True)
            continue

        result.append(True)
        closing = re.match(r"^ *(" + re.escape(marker) + r"+)[ \t]*(?:\r?\n)?$", line)
        if closing is not None and len(closing.group(1)) >= minimum:
            marker = None
            minimum = 0
    return result


def heading_text(raw: str) -> str:
    text = raw.strip()
    text = re.sub(r"#+$", "", text)
    return text.rstrip()


def inline_destinations(line: str) -> list[tuple[int, int, str, bool]]:
    """Find link destination spans, including balanced bare destinations."""
    found: list[tuple[int, int, str, bool]] = []
    index = 0
    limit = len(line)
    while index < limit:
        start = index
        if line[index] == "!" and index + 1 < limit and line[index + 1] == "[":
            bracket = index + 1
        elif line[index] == "[":
            bracket = index
        else:
            index += 1
            continue

        depth = 1
        cursor = bracket + 1
        while cursor < limit and depth:
            if line[cursor] == "\\" and cursor + 1 < limit:
                cursor += 2
                continue
            if line[cursor] == "[":
                depth += 1
            elif line[cursor] == "]":
                depth -= 1
            cursor += 1
        if depth or cursor >= limit or line[cursor] != "(":
            index = start + 1
            continue

        destination_start = cursor + 1
        if destination_start < limit and line[destination_start] == "<":
            value_start = destination_start + 1
            cursor = value_start
            while cursor < limit:
                if line[cursor] == "\\" and cursor + 1 < limit:
                    cursor += 2
                    continue
                if line[cursor] == ">":
                    break
                cursor += 1
            if cursor >= limit or cursor + 1 >= limit or line[cursor + 1] != ")":
                index = start + 1
                continue
            found.append((value_start, cursor, line[value_start:cursor], True))
            index = cursor + 2
            continue

        value_start = destination_start
        cursor = value_start
        paren_depth = 1
        while cursor < limit and paren_depth:
            if line[cursor] == "\\" and cursor + 1 < limit:
                cursor += 2
                continue
            if line[cursor] == "(":
                paren_depth += 1
            elif line[cursor] == ")":
                paren_depth -= 1
                if paren_depth == 0:
                    break
            cursor += 1
        if paren_depth:
            index = start + 1
            continue
        found.append((value_start, cursor, line[value_start:cursor], False))
        index = cursor + 1
    return found


def inspect_document(text: str) -> tuple[DocumentInfo, list[tuple[int, int, str, bool]]]:
    """Collect headings and destination spans outside fenced code blocks."""
    lines = text.splitlines(keepends=True)
    fenced = fence_lines(lines)
    headings: list[Heading] = []
    base_counts: dict[str, int] = {}
    title = ""
    found_title = False
    links: list[tuple[int, int, str, bool]] = []
    offset = 0

    for line, is_fenced in zip(lines, fenced):
        if not is_fenced:
            match = HEADING_RE.match(line)
            if match is not None:
                text_value = heading_text(match.group(2) or "")
                base = normalize_anchor(text_value)
                occurrence = base_counts.get(base, 0)
                anchor = base if occurrence == 0 else f"{base}-{occurrence}"
                base_counts[base] = occurrence + 1
                headings.append(Heading(text_value, anchor))
                if not found_title and len(match.group(1)) == 1:
                    title = text_value
                    found_title = True

            for start, end, destination, angled in inline_destinations(line):
                links.append((offset + start, offset + end, destination, angled))
        offset += len(line)

    return DocumentInfo(title, tuple(headings)), links


def normalize_root_path(source_parent: PurePosixPath, path: str) -> str | None:
    """Lexically resolve a POSIX path, rejecting paths above the KB root."""
    if path.startswith("/"):
        return None
    parts: list[str] = []
    for part in (*source_parent.parts, *PurePosixPath(path).parts):
        if part in ("", "."):
            continue
        if part == "..":
            if not parts:
                return None
            parts.pop()
        else:
            parts.append(part)
    return "/".join(parts)


def replacement_target(
    original: str,
    source_path: str,
    kb_root: Path,
    redirects: dict[str, list[str]],
    documents: dict[str, DocumentInfo],
) -> LinkResult:
    if original.startswith("/") or SCHEME_RE.match(original):
        return LinkResult(None, "", "external")

    if "#" in original:
        raw_path, fragment = original.split("#", 1)
        has_fragment = True
    else:
        raw_path, fragment = original, ""
        has_fragment = False

    source = PurePosixPath(source_path)
    if raw_path:
        target_path = normalize_root_path(source.parent, raw_path)
    else:
        target_path = source_path
    if target_path is None:
        return LinkResult(None, "", "unresolved")

    path_repaired = False
    target_on_disk = kb_root.joinpath(*PurePosixPath(target_path).parts)
    if not target_on_disk.exists():
        choices = redirects.get(target_path)
        if not isinstance(choices, list) or len(choices) != 1 or not isinstance(choices[0], str):
            return LinkResult(None, "", "unresolved")
        redirected = normalize_root_path(PurePosixPath(), choices[0])
        if redirected is None:
            return LinkResult(None, "", "unresolved")
        redirected_on_disk = kb_root.joinpath(*PurePosixPath(redirected).parts)
        if not redirected_on_disk.exists():
            return LinkResult(None, "", "unresolved")
        target_path = redirected
        target_on_disk = redirected_on_disk
        path_repaired = True

    fragment_repaired = False
    final_fragment = fragment
    if has_fragment and target_path.lower().endswith(".md"):
        document = documents.get(target_path)
        if document is None:
            return LinkResult(None, "", "unresolved")
        anchors = [heading.anchor for heading in document.headings]
        if fragment not in anchors:
            candidate = normalize_anchor(fragment)
            if anchors.count(candidate) != 1:
                return LinkResult(None, "", "unresolved")
            final_fragment = candidate
            fragment_repaired = True

    resolved = target_path + ("#" + final_fragment if has_fragment else "")
    if not path_repaired and not fragment_repaired:
        return LinkResult(None, resolved, "ok")

    if not raw_path:
        relative = ""
    else:
        relative = posixpath.relpath(target_path, str(source.parent))
        if relative == ".":
            relative = ""
    rewritten = relative + ("#" + final_fragment if has_fragment else "")
    return LinkResult(rewritten, resolved, "repaired")


def read_redirects(path: Path) -> dict[str, list[str]]:
    value = json.loads(path.read_bytes().decode("utf-8"))
    if not isinstance(value, dict):
        raise ValueError("redirects JSON must contain an object")
    return value


def markdown_files(root: Path) -> list[tuple[str, Path]]:
    files = ((path.relative_to(root).as_posix(), path) for path in root.rglob("*.md"))
    return sorted(files, key=lambda item: item[0])


def write_csv(path: Path, rows: Iterable[dict[str, str]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(
            stream,
            fieldnames=("source_path", "original_target", "resolved_target", "status"),
            lineterminator="\n",
        )
        writer.writeheader()
        writer.writerows(rows)


def remove_tree(path: Path) -> None:
    """Remove a possibly read-only tree left by a mode-preserving copy."""
    for directory in (item for item in path.rglob("*") if item.is_dir()):
        directory.chmod(directory.stat().st_mode | stat.S_IWUSR | stat.S_IXUSR)
    path.chmod(path.stat().st_mode | stat.S_IWUSR | stat.S_IXUSR)
    shutil.rmtree(path)


def write_repaired_file(path: Path, data: bytes) -> None:
    """Write content while retaining the copied input file's permission bits."""
    mode = stat.S_IMODE(path.stat().st_mode)
    path.chmod(mode | stat.S_IWUSR)
    try:
        path.write_bytes(data)
    finally:
        path.chmod(mode)


def run(kb_root: Path, redirects_path: Path, output: Path) -> None:
    redirects = read_redirects(redirects_path)
    md_files = markdown_files(kb_root)
    texts: dict[str, str] = {}
    documents: dict[str, DocumentInfo] = {}
    link_spans: dict[str, list[tuple[int, int, str, bool]]] = {}

    for relative, path in md_files:
        text = path.read_bytes().decode("utf-8")
        info, links = inspect_document(text)
        texts[relative] = text
        documents[relative] = info
        link_spans[relative] = links

    output.mkdir(parents=True, exist_ok=True)
    copied_kb = output / "kb"
    if copied_kb.exists() or copied_kb.is_symlink():
        if copied_kb.is_dir() and not copied_kb.is_symlink():
            remove_tree(copied_kb)
        else:
            copied_kb.unlink()
    shutil.copytree(kb_root, copied_kb)

    report: list[dict[str, str]] = []
    index: dict[str, dict[str, object]] = {}
    for source_path, _ in md_files:
        text = texts[source_path]
        changes: list[tuple[int, int, str]] = []
        outgoing: list[str] = []
        for start, end, original, angled in link_spans[source_path]:
            result = replacement_target(
                original, source_path, kb_root, redirects, documents
            )
            report.append(
                {
                    "source_path": source_path,
                    "original_target": original,
                    "resolved_target": result.resolved_target,
                    "status": result.status,
                }
            )
            if result.status in ("ok", "repaired"):
                outgoing.append(result.resolved_target)

                outgoing.append(result.resolved_target)
            if result.replacement is not None:
                changes.append((start, end, result.replacement))

        if changes:
            for start, end, replacement in reversed(changes):
                text = text[:start] + replacement + text[end:]
            destination = copied_kb.joinpath(*PurePosixPath(source_path).parts)
            write_repaired_file(destination, text.encode("utf-8"))

        info = documents[source_path]
        index[source_path] = {
            "title": info.title,
            "headings": [
                {"text": heading.text, "anchor": heading.anchor}
                for heading in info.headings
            ],
            "outgoing_local_links": outgoing,
        }

    write_csv(output / "link_report.csv", report)
    with (output / "index.json").open("w", encoding="utf-8", newline="\n") as stream:
        json.dump(index, stream, ensure_ascii=False, sort_keys=True, indent=2)
        stream.write("\n")


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("kb", type=Path)
    parser.add_argument("--redirects", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        run(args.kb, args.redirects, args.output)
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as error:
        print(f"kb_repair: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
